"ウダーナ バッディヤ・スッタ ダンマパダ":"8f2b10368e8a",
"王族として守りに囲まれ、それでも怯えていた者が、出家して森の木の下に坐り、繰り返しつぶやいた。ああ、なんという安らぎだろう、と。":"1326bf211dc3",
