"ダンマパダ四百番は、怒りを離れた者を揺るがない者として描く。揺らがないのは、我慢して立っているからではない。押し返すべきものが、もう見つからないからである。":"bebd3942595a",
"怒りが鎮まった状態は、病から回復したときにたとえられる。":"63054a62301e",
