"如理作意 慈心解脱":"ad021a17eff0",
"アーハーラ経は、怒りを痩せさせるものとして、慈しみによる心の解放を挙げる。注釈の伝統では、これを慈・悲・喜・捨の四つとして展開する。":"673b6411bbff",
"描かれているのは、我慢している状態ではない。心が広くなった状態である。":"4fd03dfbfcc8",
"古くから使われるたとえがある。広い場所に一握りの塩を落としても水は塩辛くならない。同じ塩を小さな器に落とせば、飲めなくなる。塩の量は変わっておらず、器の大きさだけが違う。":"386a20492639",
"出来事の大きさは、こちらで決められない。決められるのは器のほうである。確かめるべきは、許すという作業が要らないところまで広がっているかどうかである。":"7f1c57852d2c",
"コーダナ・スッタ 後半":"28d69e9c299b",
