"死の使いたちが、傍らに立っている。":"727c951f30a6",
"旅立ちの入口にいるのに、道の糧を持っていない。":"32307e812986",
"ならば、自らの島を作れ。速やかに励め。賢くあれ。":"7860b1f8a97b",
"死に捕らえられた者にとって、":"758396752053",
"子も、父も、親族も、逃れ場にはならない。":"624655da25e9",
"身内のうちに、避難所はない。":"9239af0bc2dd",
"これを知る賢者は、道を切り開くことに向かう。":"8737a1ddc75b",
"家を作る者よ、おまえは見られた。":"51f70d2e53c9",
"もう二度と家を建てることはない。":"03af322f0eb0",
"垂木はすべて折れ、棟木は砕けた。":"e76f7b9807a0",
"見られてしまえば、それは建たない。見るまでは、建ち続ける。":"b10897574021",
"「わずかだから」と、悪を軽んじてはならない。":"e2d15699dbe6",
"一滴ずつ落ちて、水瓶は満たされる。":"3c5d554f065d",
"満ちるまで、誰も気づかない。":"0d420e556c03",
"「わずかだから」と、善を軽んじてはならない。":"3d46820f3a34",
"今日の一坐も、その一滴である。":"41fbc7d52e3d",
"五つの観察":"3081c856a30f",
"私は老いる。老いを避けられない。":"ac4be290e9eb",
"私は病む。病を避けられない。":"75b5d935f36b",
"私は死ぬ。死を避けられない。":"b9870e7c17d1",
"愛するものすべてと、いつか別れる。":"b34e739ac6f2",
"私は自らの行いを継ぐ者であり、行いから逃れられない。":"a696d3c61c0b",
"毎日これを思い返せ、と説かれる。忘れていられる時間のほうが、異常なのである。":"b21999466935",
