"私はいま、そのどれでもない。この一致は、当たり前ではない。":"3dd4ddfdec9f",
"盲亀浮木":"1a198e26085f",
"大海に、ひとつだけ穴の空いた軛が漂っている。":"8cea711bb8cc",
