"正しい努力":"1f97c9adefae",
"まだ起きていない悪を、起こさせないこと。":"c9d17f0fd7b4",
"すでに起きた悪を、捨てること。":"a03acf16bb89",
"まだ起きていない善を、起こすこと。":"7fa4bc5a52c1",
"すでに起きた善を、保ち、増やすこと。":"1cdf616e28ba",
"四つとも、いまこの瞬間に始められる。":"c3a72889e22a",
"ウダーナ 涅槃":"a61561e0466f",
"生まれず、成らず、作られず、形づくられないものがある。":"99003a46a3cd",
"もしそれが無ければ、":"633dea7202f2",
"生まれ、成り、作られ、形づくられたものからの出口も無い。":"95b465eaaa2c",
"しかし、それはある。だから、出口はある。":"1067ae594273",
"梵天勧請":"73072c1b7470",
"この教えは、流れに逆らう、と告げられた。":"a2551b2fc065",
