"捨てたのは道具ではなく、道具に縛られていた歳月であった。":"1b016821378a",
"テーラガーター アングリマーラ 雲を離れた月":"de2ae8e07ce1",
"私は九百九十九人を殺し、その指を数えて首にかけていた。":"711793c7d731",
