"テーリーガーター アンバパーリー 髪と歯と":"ac8e1da97a7d",
"私は国中に名を知られた遊女で、一夜の値は国の一日の稼ぎに等しかった。":"5c1431059890",
"私の髪は黒く、蜂のようで、先が巻いていた。":"9abaa9c8a98f",
