"そのすべてで、同じことを繰り返してきた。":"0f799a82ddc6",
"いま、繰り返しが終わる。":"1852f085b285",
"次に何になるかを心配する必要が、もう無い。":"a4f8bab53270",
"テーリーガーター ナンダー 美しい妹":"ffec9aa11765",
"私は仏の妹で、自分の美しさを誇っていた。":"5d2ead409336",
"出家してからも、仏に会うのを避けていた。醜さを説かれると聞いたからである。":"cca9fe6ec327",
