"私は自分の身体を見た。同じものであった。":"596e918fe4aa",
"順番が来ていないだけであった。":"d76060ce9687",
"それを見た日に、私は覚った。誇るものは、もう残っていない。":"cb1b225b9698",
"テーラガーター チューラパンタカ 一句も覚えられず":"0de8dd2e5382",
"私は愚かで、四か月かけても一つの詩句を覚えられなかった。":"2e5a8bb978c9",
"兄は私を追い出そうとし、私は門の外で泣いていた。":"6295417ad03b",
