"一句も覚えられなかった者が、そこへ着いた。":"5711801b0722",
"テーリーガーター パターチャーラーの弟子たち 三十人":"af9527e04d83",
"私たちは三十人、それぞれに子を失い、家を失って集まった。":"2e44bc5bc371",
"長老尼は言った。":"ff8f1b41bb1b",
