"三十人ぶんの嘆きが、一度に消えた。":"b319a7cd7f70",
"テーラガーター サーミッディ 若さのままに":"77233e32e3ec",
"私はまだ若く、道を歩みはじめたばかりであった。":"9d29641ac343",
