"私は時を知っているので、いま歩く。":"fd399cd237e1",
"声は消えた。":"6b38eb13bd81",
"その若さのまま、私は着いた。あとで、は来なかったからである。":"b3fd48571d47",
"テーラガーター 共通の結び なすべきことは終えた":"46848f801d1e",
