"なすべきことは、なし終えた。":"70a7ca6e154d",
"この上、なすべきことはない。":"82c9a1bb998f",
"── 多くの長老・長老尼が、最後にこの一句で詩を閉じている。":"1518b554cc73",
"言えるようになるまで、坐る。それだけである。":"a6aed87c999d",
"テーラガーター マハーカッチャーナ 仕事を増やすな":"faff297d8c3c",
"私は王の使者として仏のもとへ遣わされ、そのまま出家した。":"a8d15d7e61c7",
"多くの仕事をするな。人を避けよ。忙しく動き回るな。":"8ff1f9c7dea8",
