"引いていくことで、私は着いた。もう、足すものは無い。":"bc0751a16fcf",
"テーラガーター ラーマネーヤカ 鳥の声のなかで":"5a13026936c3",
"私は静かな場所を探して、林から林へ移り歩いた。":"9fdc276a1ce3",
