"値がついていたあいだ、私は自分のものではなかった。":"a98f0404c449",
"いま、値のつかない者になった。渇きは涸れ、縛めは断たれた。":"ad3b4e52ae50",
"テーラガーター バックラ 八十年病まず":"1d96371e4b19",
"私は八十歳で出家し、それから八十年、修行を続けた。":"696ec8ce3457",
