"遅く始めた者に残されているのは、いま起きていることだけであった。":"e9a9da83097f",
"その一つで足りた。なすべきことは、なし終えた。":"b91b4a877809",
"テーラガーター プンナ 打たれても":"4124f4bd4e74",
"遠国へ行く許可を求めた私に、仏は問われた。":"e49445ba845e",
"あの土地の者は荒い。罵られたらどうする。":"5b4feede7d6a",
