"殺されたら。":"47b3cb567638",
"── この身を厭う者にとって、手間が省けます。":"63be3ca419c4",
"仏は言われた。行きなさい。":"4a63d11151d4",
"私はその地で五百人を教えに導き、そこで生を終えた。":"355d9d3ba833",
"覚悟が守ったのではない。守るものが、もう無かった。":"d61afa10b26c",
"テーラガーター ソーナ・コーリヴィーサ 琴の弦":"62512235e1a0",
"私は柔らかく育ち、足の裏に毛が生えていると言われた。":"d32662638e12",
