"修行も同じである、と言われた。":"4468e2ba044b",
"締めるのをやめた日から、初めて音が出た。":"43aaee90a711",
"血を流した年月ではなく、力を抜いた一日が、私を運んだ。":"30f9d1ed7c4f",
